    "params": [
      {
        "name": "a",
        "description": "Baud rate",
        "values": "e.g. 9600"
      },
      {
        "name": "b",
        "description": "Word length",
        "values": "7 or 8 data bits"
      },
      {
        "name": "c",
        "description": "Parity",
        "values": "N none, E even, O odd"
      },
      {
        "name": "d",
        "description": "Stop bits",
        "values": "1 or 2"
      },
      {
        "name": "e",
        "description": "Handshake (protocol mode)",
        "values": "X XON/XOFF, D DTR/DSR, R RTS, M DTR/DSR XON/XOFF (G-Series only)"
      },
      {
        "name": "f",
        "description": "Zebra protocol",
        "values": "A ACK/NAK, N none, Z Zebra"
      }
    ]
